/**
 * This browser's account identity: an Ed25519 signing key and an X25519 Noise
 * key, both generated by WebCrypto as non-extractable keys. Script running on
 * the page can use them, but no script can read the private halves out, so a
 * copy of the browser's storage alone doesn't clone the device.
 */

import type { AsyncEntrySigner, DeviceMember } from "@argus/remote-protocol/account";
import { fromB64, toB64 } from "@argus/remote-protocol/account";
import type { AsyncStaticKey } from "@argus/remote-client";

export interface WebDeviceKeys {
  memberId: string;
  name: string;
  createdAt: number;
  signPub: string;
  noisePub: string;
  /** Ed25519 private key, non-extractable. */
  signKey: CryptoKey;
  /** X25519 private key, non-extractable. */
  noiseKey: CryptoKey;
}

const ED25519 = { name: "Ed25519" } as const;
const X25519 = { name: "X25519" } as const;

/** WebCrypto wants buffers it owns; this also strips any SharedArrayBuffer view. */
const own = (bytes: Uint8Array): Uint8Array<ArrayBuffer> => new Uint8Array(bytes);

async function rawPublic(subtle: SubtleCrypto, key: CryptoKey): Promise<string> {
  return toB64(new Uint8Array(await subtle.exportKey("raw", key)));
}

/** Ed25519 and X25519 in WebCrypto: Chrome 137+, Safari 17+, Firefox 130+. */
export async function webCryptoSupported(
  subtle: SubtleCrypto | undefined = globalThis.crypto?.subtle,
): Promise<boolean> {
  if (!subtle) {
    return false;
  }
  try {
    await subtle.generateKey(ED25519, false, ["sign", "verify"]);
    await subtle.generateKey(X25519, false, ["deriveBits"]);

    return true;
  } catch {
    return false;
  }
}

export async function generateDeviceKeys(
  name: string,
  now: number,
  subtle: SubtleCrypto = crypto.subtle,
): Promise<WebDeviceKeys> {
  const sign = (await subtle.generateKey(ED25519, false, [
    "sign",
    "verify",
  ])) as CryptoKeyPair;
  const noise = (await subtle.generateKey(X25519, false, [
    "deriveBits",
  ])) as CryptoKeyPair;

  return {
    memberId: crypto.randomUUID(),
    name,
    createdAt: now,
    signPub: await rawPublic(subtle, sign.publicKey),
    noisePub: await rawPublic(subtle, noise.publicKey),
    signKey: sign.privateKey,
    noiseKey: noise.privateKey,
  };
}

export function deviceMember(keys: WebDeviceKeys): DeviceMember {
  return {
    id: keys.memberId,
    role: "device",
    kind: "web",
    sign_pub: keys.signPub,
    noise_pub: keys.noisePub,
    name: keys.name,
    created_at: keys.createdAt,
  };
}

export async function signWith(
  keys: WebDeviceKeys,
  message: Uint8Array,
  subtle: SubtleCrypto = crypto.subtle,
): Promise<Uint8Array> {
  return new Uint8Array(await subtle.sign(ED25519, keys.signKey, own(message)));
}

/** X25519(this device's Noise key, `remotePub`). */
export async function dhWith(
  keys: WebDeviceKeys,
  remotePub: Uint8Array,
  subtle: SubtleCrypto = crypto.subtle,
): Promise<Uint8Array> {
  const remote = await subtle.importKey("raw", own(remotePub), X25519, true, []);
  const bits = await subtle.deriveBits(
    { name: "X25519", public: remote },
    keys.noiseKey,
    256,
  );

  return new Uint8Array(bits);
}

export function entrySigner(keys: WebDeviceKeys): AsyncEntrySigner {
  return { id: keys.memberId, sign: (message) => signWith(keys, message) };
}

/** The Noise static key the transport dials account hosts with. */
export function noiseStaticKey(keys: WebDeviceKeys): AsyncStaticKey {
  return { pub: fromB64(keys.noisePub), dh: (remote) => dhWith(keys, remote) };
}
